"""Freight charges for parcel shipments. The rules are specified in SPEC.md."""
from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_UP

import re


class RateError(ValueError):
    """Raised for shipments that SPEC.md declares invalid."""


@dataclass(frozen=True)
class Shipment:
    origin: str  # 5-digit postal code
    destination: str  # 5-digit postal code
    weight_kg: Decimal
    length_cm: int
    width_cm: int
    height_cm: int
    month: int  # shipping month, 1..12
    customer: str = "standard"  # "standard" or a contract code
    service: str = "ground"  # "ground" or "express"


# Zone lookup table
ZONE_TABLE = {
    "A": {
        "A": Decimal("1"), "B": Decimal("2"), "C": Decimal("3"), "D": Decimal("4"),
        "E": Decimal("5"), "F": Decimal("6"), "G": Decimal("6"), "H": Decimal("3"),
    },
    "B": {
        "A": Decimal("2"), "B": Decimal("1"), "C": Decimal("2"), "D": Decimal("4"),
        "E": Decimal("4"), "F": Decimal("5"), "G": Decimal("6"), "H": Decimal("6"),
    },
    "C": {
        "A": Decimal("3"), "B": Decimal("2"), "C": Decimal("1"), "D": Decimal("3"),
        "E": Decimal("3"), "F": Decimal("4"), "G": Decimal("5"), "H": Decimal("6"),
    },
    "D": {
        "A": Decimal("4"), "B": Decimal("4"), "C": Decimal("3"), "D": Decimal("1"),
        "E": Decimal("3"), "F": Decimal("4"), "G": Decimal("4"), "H": Decimal("5"),
    },
    "E": {
        "A": Decimal("5"), "B": Decimal("4"), "C": Decimal("3"), "D": Decimal("3"),
        "E": Decimal("1"), "F": Decimal("3"), "G": Decimal("3"), "H": Decimal("5"),
    },
    "F": {
        "A": Decimal("6"), "B": Decimal("5"), "C": Decimal("4"), "D": Decimal("4"),
        "E": Decimal("3"), "F": Decimal("1"), "G": Decimal("2"), "H": Decimal("3"),
    },
    "G": {
        "A": Decimal("6"), "B": Decimal("6"), "C": Decimal("5"), "D": Decimal("4"),
        "E": Decimal("3"), "F": Decimal("2"), "G": Decimal("1"), "H": Decimal("2"),
    },
    "H": {
        "A": Decimal("3"), "B": Decimal("6"), "C": Decimal("6"), "D": Decimal("5"),
        "E": Decimal("5"), "F": Decimal("3"), "G": Decimal("2"), "H": Decimal("1"),
    },
}

# Base tariff by zone and service
BASE_TARIFF = {
    "ground": {
        "1": Decimal("6.25"), "2": Decimal("7.10"), "3": Decimal("7.95"), "4": Decimal("8.80"),
        "5": Decimal("9.65"), "6": Decimal("10.50"),
    },
    "express": {
        "1": Decimal("11.25"), "2": Decimal("12.78"), "3": Decimal("14.31"), "4": Decimal("15.84"),
        "5": Decimal("17.37"), "6": Decimal("18.90"),
    },
}

# First kg price and each extra 0.5 kg price
TARIFF_EXTRA = {
    "ground": {
        "1": Decimal("0.82"), "2": Decimal("1.04"), "3": Decimal("1.26"), "4": Decimal("1.48"),
        "5": Decimal("1.70"), "6": Decimal("1.92"),
    },
    "express": {
        "1": Decimal("1.31"), "2": Decimal("1.66"), "3": Decimal("2.02"), "4": Decimal("2.37"),
        "5": Decimal("2.72"), "6": Decimal("3.07"),
    },
}

# Fuel surcharge by month
FUEL_SURCHARGE = {
    1: Decimal("0.0875"), 2: Decimal("0.0850"), 3: Decimal("0.0925"), 4: Decimal("0.0900"),
    5: Decimal("0.0925"), 6: Decimal("0.0950"), 7: Decimal("0.1025"), 8: Decimal("0.1050"),
    9: Decimal("0.1025"), 10: Decimal("0.1050"), 11: Decimal("0.1025"), 12: Decimal("0.1100"),
}

# Contract discount percentages
CONTRACT_DISCOUNT = {
    "ACME": {"ground": Decimal("0.12"), "express": Decimal("0.12")},
    "GLOBEX": {"ground": Decimal("0.08"), "express": Decimal("0.08")},
    "INITECH": {"ground": Decimal("0.00"), "express": Decimal("0.15")},
    "UMBRELLA": {"ground": Decimal("0.05"), "express": Decimal("0.05")},
}

# Remote destination codes
REMOTE_CODES = {"085", "086", "131", "314", "349", "399", "451", "698", "757", "855", "923", "941"}


def rate(shipment: Shipment) -> Decimal:
    """Return the freight charge in EUR, following SPEC.md section 9 ("Calculation order")."""
    # 1. Validate the shipment (section 8)
    _validate(shipment)

    # 2. Compute the billable weight (section 4)
    billable_weight = _compute_billable_weight(shipment)

    # 3. Look up the zone from the origin and destination regions (sections 2 and 3)
    zone = _lookup_zone(shipment)

    # 4. Compute the base charge (section 5)
    base_charge = _compute_base_charge(zone, shipment)

    # 5. Add the fuel surcharge on the base charge (6.1)
    fuel_surcharge = _apply_fuel_surcharge(base_charge, shipment)

    # 6. Apply the contract discount to base + fuel (section 7)
    after_discount = _apply_contract_discount(base_charge + fuel_surcharge, shipment)

    # 7. Add the flat surcharges that apply (6.2, 6.3, 6.4)
    total = after_discount + _apply_flat_surcharges(shipment)

    # 8. Round the total half-up to 0.01
    total = total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

    # 9. If the result is below the minimum charge of 6.90, charge 6.90
    if total < Decimal("6.90"):
        total = Decimal("6.90")

    return total


def _validate(shipment: Shipment) -> None:
    """Validate the shipment according to section 8."""
    # Postal code must be exactly 5 digits
    if not re.match(r"^\d{5}$", shipment.origin) or not re.match(r"^\d{5}$", shipment.destination):
        raise RateError("Postal code must be exactly 5 digits")

    # Weight must be greater than 0 and not above 70 kg
    if shipment.weight_kg <= Decimal("0"):
        raise RateError("Weight must be greater than 0 kg")
    if shipment.weight_kg > Decimal("70"):
        raise RateError("Weight must not exceed 70 kg")

    # Each dimension must be at least 1 cm
    if shipment.length_cm < 1 or shipment.width_cm < 1 or shipment.height_cm < 1:
        raise RateError("All dimensions must be at least 1 cm")

    # Month must be 1-12
    if not (1 <= shipment.month <= 12):
        raise RateError("Month must be between 1 and 12")

    # Service must be ground or express
    if shipment.service not in ("ground", "express"):
        raise RateError("Service must be ground or express")

    # Customer must be standard or a valid contract code
    if shipment.customer not in ("standard", "ACME", "GLOBEX", "INITECH", "UMBRELLA"):
        raise RateError("Customer must be standard or a valid contract code")


def _compute_billable_weight(shipment: Shipment) -> Decimal:
    """Compute billable weight according to section 4."""
    # Volumetric weight = length × width × height / divisor
    volumetric_weight = Decimal(shipment.length_cm) * Decimal(shipment.width_cm) * Decimal(shipment.height_cm) / Decimal(5000)

    # Billable weight is the largest of: actual weight, volumetric weight, and 1.0 kg
    billable = shipment.weight_kg
    if volumetric_weight > billable:
        billable = volumetric_weight
    if Decimal("1.0") > billable:
        billable = Decimal("1.0")

    # Round up to the next multiple of 0.5 kg
    billable = _round_up_half(billable)

    return billable


def _round_up_half(value: Decimal) -> Decimal:
    """Round up to the next multiple of 0.5."""
    return (value + Decimal("0.25")).quantize(Decimal("0.5"), rounding=ROUND_HALF_UP)


def _lookup_zone(shipment: Shipment) -> str:
    """Look up the zone from origin and destination regions."""
    origin_region = _get_region(shipment.origin)
    destination_region = _get_region(shipment.destination)

    return origin_region

    # Actually, zone is a number from the table, not a region name. Let me fix this.
    zone_num = ZONE_TABLE[origin_region][destination_region]
    return zone_num


def _get_region(postal_code: str) -> str:
    """Get the region from the first two digits of the postal code."""
    first_two = postal_code[:2]
    if first_two <= "11":
        return "A"
    elif first_two <= "23":
        return "B"
    elif first_two <= "35":
        return "C"
    elif first_two <= "47":
        return "D"
    elif first_two <= "59":
        return "E"
    elif first_two <= "71":
        return "F"
    elif first_two <= "85":
        return "G"
    else:
        return "H"


def _compute_base_charge(zone: Decimal, shipment: Shipment) -> Decimal:
    """Compute base charge according to section 5."""
    service = shipment.service
    zone_num = int(zone)

    first_kg = BASE_TARIFF[service][zone_num]
    extra_per_05kg = TARIFF_EXTRA[service][zone_num]

    # Base charge is first kg price plus each additional 0.5 kg above 1.0 kg
    billable = shipment.weight_kg
    if billable <= Decimal("1.0"):
        return first_kg

    # Number of additional 0.5 kg units
    additional = (billable - Decimal("1.0")) / Decimal("0.5")
    return first_kg + (additional * extra_per_05kg)


def _apply_fuel_surcharge(base_charge: Decimal, shipment: Shipment) -> Decimal:
    """Add fuel surcharge on the base charge."""
    fuel_percent = FUEL_SURCHARGE[shipment.month]
    return base_charge * (1 + fuel_percent)


def _apply_contract_discount(total: Decimal, shipment: Shipment) -> Decimal:
    """Apply contract discount to base + fuel."""
    if shipment.customer == "standard":
        return total

    if shipment.customer in CONTRACT_DISCOUNT:
        discount_rate = CONTRACT_DISCOUNT[shipment.customer][shipment.service]
        return total * (1 - discount_rate)

    raise RateError("Invalid customer code")


def _apply_flat_surcharges(shipment: Shipment) -> Decimal:
    """Add flat surcharges that apply (6.2, 6.3, 6.4)."""
    result = Decimal("0")

    # 6.2 Remote destinations: flat 7.50 if first three digits are in the list
    code = shipment.origin[:3]
    if code in REMOTE_CODES:
        result += Decimal("7.50")

    # 6.3 Oversize: flat 25.00 if longest side > 120 cm, or if longest + 2*(sum of others) > 300
    max_side = max(shipment.length_cm, shipment.width_cm, shipment.height_cm)
    if max_side > Decimal("120"):
        result += Decimal("25.00")
    elif max_side + 2 * (shipment.length_cm + shipment.width_cm + shipment.height_cm) > Decimal("300"):
        result += Decimal("25.00")

    # 6.4 Heavy parcels: flat 15.00 if billable weight > 30 kg
    billable = _compute_billable_weight(shipment)
    if billable > Decimal("30"):
        result += Decimal("15.00")

    return result

