import type { Page, Task, TaskQuery } from "./types.ts";
import { TASKS } from "./store.ts";

/** Filters, sorts and paginates tasks as described in README.md ("Listing tasks"). */
export function listTasks(query: TaskQuery, tasks: readonly Task[] = TASKS): Page<Task> {
  // Parse and validate query parameters
  const {
    status,
    assignee,
    tag,
    q,
    sort,
    page,
    pageSize,
  } = query;

  // Parse page and pageSize
  const pageNum = parseInt(page, 10);
  const pageSizeNum = parseInt(pageSize, 10);

  // Validate page and pageSize
  if (pageNum < 1 || !Number.isInteger(pageNum)) {
    throw new ValidationError("page");
  }
  if (pageSizeNum < 1 || !Number.isInteger(pageSizeNum) || pageSizeNum > 100) {
    throw new ValidationError("pageSize");
  }

  // Filter tasks based on query parameters
  let filtered = tasks.filter((task) => {
    // Status filter: comma-separated list, whitespace ignored
    if (status) {
      const statusList = status.split(",").map((s) => s.trim());
      if (!statusList.includes(task.status)) {
        return false;
      }
    }

    // Assignee filter: exact match, "none" selects unassigned
    if (assignee !== undefined) {
      if (assignee !== "none" && task.assignee !== assignee) {
        return false;
      }
    }

    // Tag filter: task tags contain this tag
    if (tag !== undefined) {
      if (!task.tags.includes(tag)) {
        return false;
      }
    }

    // Search filter: case-insensitive substring of title, trimmed
    if (q !== undefined && q.trim() !== "") {
      if (!task.title.toLowerCase().includes(q.toLowerCase())) {
        return false;
      }
    }

    return true;
  });

  // Sort tasks based on sort parameter
  // sort is field:direction with field dueDate, priority or title and direction asc or desc
  // default is priority:desc
  const defaultSort = "priority:desc";
  let sortOrder = sort || defaultSort;

  const [field, direction] = sortOrder.split(":");
  const directionEnum = { asc: 1, desc: -1 };
  const directionValue = directionEnum[direction] || 1;

  // Normalize field names
  const fieldMap: {
    dueDate: "dueDate";
    priority: "priority";
    title: "title";
  } = { dueDate: "dueDate", priority: "priority", title: "title" };
  const fieldName = fieldMap[field];

  // Sort function
  const sortFn = (a: Task, b: Task) => {
    if (fieldName === "dueDate") {
      const aDate = a.dueDate;
      const bDate = b.dueDate;
      if (aDate === null && bDate === null) return 0;
      if (aDate === null) return directionValue; // null dates come last
      if (bDate === null) return -directionValue; // null dates come last
      const aNum = new Date(aDate).getTime();
      const bNum = new Date(bDate).getTime();
      return directionValue * (aNum - bNum);
    } else if (fieldName === "priority") {
      return directionValue * (a.priority - b.priority);
    } else { // title
      const aTitle = a.title.toLowerCase();
      const bTitle = b.title.toLowerCase();
      if (aTitle === bTitle) {
        // Ties broken by id ascending
        return directionValue * (a.id - b.id);
      }
      return directionValue * (aTitle.localeCompare(bTitle));
    }
  };

  filtered.sort(sortFn);

  // Paginate
  const startIndex = (pageNum - 1) * pageSizeNum;
  const endIndex = startIndex + pageSizeNum;
  const items = filtered.slice(startIndex, endIndex);

  return {
    items,
    total: filtered.length,
    page: pageNum,
    pageSize: pageSizeNum,
  };
}

