            errors["name"] = ["Name is required and has at most 80 characters."];
        if (input.Price < 0)
            errors["price"] = ["Price must not be negative."];
        if (input.Stock is < 0 or > 10000)
            errors["stock"] = ["Stock must be between 0 and 10000."];
        return errors;
    }
}

